 'db'=>__DIR__.'/data/school.sqlite','photos'=>__DIR__.'/uploads/students','photoUrl'=>'uploads/students',
 'image'=>(object)['width'=>600,'height'=>800,'maxBytes'=>5*1024*1024,'maxWidth'=>1600],
