function db():PDO{global $cfg;static $p=null;if($p)return $p;$d=dirname($cfg->db);if(!is_dir($d))mkdir($d,0775,true);$p=new PDO('sqlite:'.$cfg->db);$p->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$p->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE,PDO::FETCH_ASSOC);$p->exec('PRAGMA foreign_keys=ON');
$p->exec("CREATE TABLE IF NOT EXISTS students(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id TEXT UNIQUE NOT NULL,student_name TEXT NOT NULL,father_name TEXT,mother_name TEXT,dob TEXT,gender TEXT NOT NULL,status TEXT,photo_path TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP)");
$p->exec("CREATE TABLE IF NOT EXISTS enrollments(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id TEXT NOT NULL,academic_session TEXT NOT NULL,class TEXT NOT NULL,section TEXT NOT NULL DEFAULT 'A',roll_no TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(student_id,academic_session),FOREIGN KEY(student_id) REFERENCES students(student_id) ON UPDATE CASCADE ON DELETE CASCADE)");
$p->exec("CREATE TABLE IF NOT EXISTS results(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id TEXT NOT NULL,academic_session TEXT NOT NULL,exam TEXT NOT NULL,subject TEXT NOT NULL,marks_obtained REAL NOT NULL,max_marks REAL NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(student_id,academic_session,exam,subject),FOREIGN KEY(student_id) REFERENCES students(student_id) ON UPDATE CASCADE ON DELETE CASCADE)");
try{$p->exec('CREATE UNIQUE INDEX IF NOT EXISTS uq_roll_per_class_session ON enrollments(academic_session,class,section,roll_no)');}catch(Throwable $e){}
$cols=$p->query('PRAGMA table_info(students)')->fetchAll();$names=array_column($cols,'name');if(!in_array('photo_path',$names,true))$p->exec('ALTER TABLE students ADD COLUMN photo_path TEXT');if(!in_array('status',$names,true)){$p->exec("ALTER TABLE students ADD COLUMN status TEXT");$st=$p->prepare("UPDATE students SET status='Active' WHERE status IS NULL AND EXISTS(SELECT 1 FROM enrollments e WHERE e.student_id=students.student_id AND e.academic_session=?)");$st->execute([$cfg->currentSession]);}$p->exec("UPDATE students SET status=CASE LOWER(TRIM(COALESCE(status,''))) WHEN 'active' THEN 'Active' WHEN 'passed out' THEN 'Passed Out' WHEN 'withdrawn' THEN 'Withdrawn' WHEN 'on hold' THEN 'On Hold' WHEN 'needs review' THEN 'Needs review' ELSE 'Needs review' END");
$ecols=$p->query('PRAGMA table_info(enrollments)')->fetchAll();foreach($ecols as $ec){if($ec['name']==='roll_no'&&(int)$ec['notnull']===1){$p->exec('DROP INDEX IF EXISTS uq_roll_per_class_session');$p->exec('ALTER TABLE enrollments RENAME TO enrollments_legacy_nullable_migration');$p->exec("CREATE TABLE enrollments(id INTEGER PRIMARY KEY AUTOINCREMENT,student_id TEXT NOT NULL,academic_session TEXT NOT NULL,class TEXT NOT NULL,section TEXT NOT NULL DEFAULT 'A',roll_no TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(student_id,academic_session),FOREIGN KEY(student_id) REFERENCES students(student_id) ON UPDATE CASCADE ON DELETE CASCADE)");$p->exec('INSERT INTO enrollments(id,student_id,academic_session,class,section,roll_no,created_at) SELECT id,student_id,academic_session,class,section,roll_no,created_at FROM enrollments_legacy_nullable_migration');$p->exec('DROP TABLE enrollments_legacy_nullable_migration');break;}}
$p->exec("UPDATE enrollments SET roll_no=NULL WHERE TRIM(COALESCE(roll_no,''))=''");try{$p->exec('CREATE UNIQUE INDEX IF NOT EXISTS uq_roll_per_class_session ON enrollments(academic_session,class,section,roll_no)');}catch(Throwable $e){}return $p;}
function out(array $x,int $s=200):never{http_response_code($s);header('Content-Type: application/json; charset=utf-8');echo json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function groupFor(string $c):string{if(in_array($c,['1','2','3'],true))return'primary';if(in_array($c,['4','5','6','7','8'],true))return'middle';if(in_array($c,['9','10'],true))return'secondary';throw new RuntimeException('Invalid class.');}
function subjectNames(string $c):array{global $cfg;$g=groupFor($c);return array_map(fn($k)=>$cfg->subjects->$k,$cfg->groups->$g);}
function fields(string $k):array{return match($k){
 'students'=>[
 ['student_id','Student ID',1,'text',['student id','student_id','admission no','id']],['student_name','Student Name',1,'text',['name','student name']],['father_name',"Father's Name",0,'text',['father','father name']],['mother_name',"Mother's Name",0,'text',['mother','mother name']],['dob','Date of Birth',0,'date',['dob','date of birth']],['gender','Gender',1,'gender',['gender','sex']],['status','Student Status',0,'status',['status','student status']]],
 'enrollments'=>[
 ['student_id','Student ID',1,'text',['student id','student_id','admission no','id']],['academic_session','Academic Session',1,'session',['session','academic session','year']],['class','Class',1,'class',['class','grade']],['section','Section',1,'section',['section','sec']],['roll_no','Roll No.',0,'text',['roll','roll no','roll number']]],
 'results'=>[
 ['student_id','Student ID',1,'text',['student id','student_id','admission no','id']],['academic_session','Academic Session',1,'session',['session','academic session','year']],['class','Class',1,'class',['class','grade']],['exam','Exam',1,'exam',['exam','exam name','assessment']],['subject','Subject',1,'subject',['subject','subject name']],['marks_obtained','Marks Obtained',1,'number',['marks','marks obtained','score']],['max_marks','Maximum Marks',1,'number',['max marks','maximum marks','out of','total marks']]],
 default=>throw new RuntimeException('Invalid type.')};}
function normRow(array $r,string $k):array{$o=[];foreach(fields($k) as $f)$o[$f[0]]=trim((string)($r[$f[0]]??''));if($k==='students'){$g=strtolower($o['gender']);$o['gender']=match($g){'m','male'=>'Male','f','female'=>'Female','o','other'=>'Other',default=>$o['gender']};$o['status']=trim((string)($o['status']??''))?:'Active';}
if($k==='results'&&$o['class']!==''){foreach((array)$GLOBALS['cfg']->subjects as $code=>$name)if(strcasecmp($o['subject'],$code)===0||strcasecmp($o['subject'],$name)===0)$o['subject']=$name;if(in_array($o['class'],['9','10'],true)&&$o['subject']==='Computer')$o['subject']='Information Technology';}return $o;}
function validate(array $r,string $k,int $i):?string{foreach(fields($k) as $f)if($f[2]&&trim((string)($r[$f[0]]??''))==='')return'Row '.$i.': '.$f[1].' is required.';global $cfg;
if($k==='students'&&!in_array($r['gender'],['Male','Female','Other'],true))return'Row '.$i.': invalid gender.';if($k==='students'&&!in_array($r['status']??'Active',['Active','Passed Out','Withdrawn','On Hold','Needs review'],true))return'Row '.$i.': invalid student status.';
if($k!=='students'){try{groupFor($r['class']);}catch(Throwable){return'Row '.$i.': invalid class.';}if(!in_array($r['academic_session'],$cfg->sessions,true))return'Row '.$i.': session not configured.';}
if($k==='results'){if(!in_array($r['exam'],$cfg->exams,true))return'Row '.$i.': exam not configured.';if(!in_array($r['subject'],subjectNames($r['class']),true))return'Row '.$i.': subject is not configured for this class.';if(!is_numeric($r['marks_obtained'])||!is_numeric($r['max_marks'])||(float)$r['max_marks']<=0||(float)$r['marks_obtained']<0||(float)$r['marks_obtained']>(float)$r['max_marks'])return'Row '.$i.': invalid marks.';}return null;}
function saveRows(string $k,array $rows,bool $overwrite):array{$p=db();$ins=$upd=$skip=0;$errors=[];$p->beginTransaction();try{foreach($rows as $i=>$raw){if(!is_array($raw))continue;$r=normRow($raw,$k);if($k==='students'&&trim((string)($raw['status']??''))==='')unset($r['status']);if($k!=='students'&&($r['academic_session']??'')!==$GLOBALS['cfg']->session){$errors[]='Row '.($i+1).': academic session must match the selected session.';continue;}$e=validate($r,$k,$i+1);if($e){$errors[]=$e;continue;}
if($k!=='students'){$q=$p->prepare('SELECT 1 FROM students WHERE student_id=?');$q->execute([$r['student_id']]);if(!$q->fetchColumn()){$errors[]='Row '.($i+1).': student ID not found.';continue;}}
if($k==='results'){$q=$p->prepare('SELECT class FROM enrollments WHERE student_id=? AND academic_session=?');$q->execute([$r['student_id'],$r['academic_session']]);$cl=$q->fetchColumn();if($cl===false){$errors[]='Row '.($i+1).': enrollment not found.';continue;}if((string)$cl!==$r['class']){$errors[]='Row '.($i+1).': class does not match enrollment.';continue;}unset($r['class']);}
$keys=['students'=>['student_id'],'enrollments'=>['student_id','academic_session'],'results'=>['student_id','academic_session','exam','subject']][$k];$where=implode(' AND ',array_map(fn($x)=>"$x=?",$keys));$q=$p->prepare("SELECT id FROM $k WHERE $where");$q->execute(array_map(fn($x)=>$r[$x],$keys));$id=$q->fetchColumn();if(!$id&&$k==='students'&&!isset($r['status']))$r['status']='Active';
if($id&&!$overwrite){$skip++;continue;}if($id){$updFields=array_values(array_diff(array_keys($r),$keys));if($updFields){$sets=implode(',',array_map(fn($x)=>"$x=?",$updFields));if(in_array($k,['students','results'],true))$sets.=',updated_at=CURRENT_TIMESTAMP';$p->prepare("UPDATE $k SET $sets WHERE $where")->execute([...array_map(fn($x)=>$r[$x],$updFields),...array_map(fn($x)=>$r[$x],$keys)]);}$upd++;}else{$cols=array_keys($r);$p->prepare("INSERT INTO $k(".implode(',',$cols).") VALUES(".implode(',',array_fill(0,count($cols),'?')).")")->execute(array_values($r));$ins++;}}
$p->commit();}catch(Throwable $e){if($p->inTransaction())$p->rollBack();throw $e;}return['inserted'=>$ins,'updated'=>$upd,'skipped'=>$skip,'errors'=>$errors];}
function photoSave(string $id,string $url):string{global $cfg;if(!preg_match('~^data:image/(jpeg|png|webp);base64,([A-Za-z0-9+/=\r\n]+)$~',$url,$m))throw new RuntimeException('Invalid image.');$bin=base64_decode($m[2],true);if(!$bin||strlen($bin)>$cfg->image->maxBytes)throw new RuntimeException('Image is invalid or too large.');$info=@getimagesizefromstring($bin);if(!$info||!in_array($info[2],[IMAGETYPE_JPEG,IMAGETYPE_PNG,IMAGETYPE_WEBP],true))throw new RuntimeException('Invalid image content.');if(!is_dir($cfg->photos))mkdir($cfg->photos,0775,true);$ext=match($info[2]){IMAGETYPE_JPEG=>'jpg',IMAGETYPE_PNG=>'png',default=>'webp'};$name=preg_replace('/[^A-Za-z0-9_-]/','_',$id).'_'.bin2hex(random_bytes(4)).'.'.$ext;file_put_contents($cfg->photos.'/'.$name,$bin);return $cfg->photoUrl.'/'.$name;}
