$cfg->sessions=availableSessions($p,$cfg);$wanted=(string)($_SESSION['academic_session']??$cfg->currentSession);if(!in_array($wanted,$cfg->sessions,true))$wanted=in_array($cfg->currentSession,$cfg->sessions,true)?$cfg->currentSession:($cfg->sessions[0]??$cfg->currentSession);$_SESSION['academic_session']=$wanted;$cfg->session=$wanted;
