if($a==='bulk_save_student_enrollments'){
 $rows=$b['rows']??[];$p->beginTransaction();$inserted=$updated=$skipped=0;$errors=[];
 try{foreach($rows as $i=>$raw){if(!is_array($raw))continue;$n=$i+1;$student=normRow($raw,'students');$en=['student_id'=>$student['student_id'],'academic_session'=>$GLOBALS['cfg']->session,'class'=>trim((string)($raw['class']??'')),'section'=>trim((string)($raw['section']??'')),'roll_no'=>trim((string)($raw['roll_no']??''))];
