  $q=$p->prepare('SELECT student_id FROM enrollments WHERE academic_session=? AND class=? AND section=? AND roll_no=? AND student_id<>?');if($en['roll_no']!=='')$q->execute([$en['academic_session'],$en['class'],$en['section'],$en['roll_no'],$en['student_id']]);if($en['roll_no']!==''&&$q->fetchColumn()){$errors[]='Row '.$n.': roll number '.$en['roll_no'].' is already used in this class, section and session.';continue;}
