  if($en['roll_no']==='')$en['roll_no']=null;if($eid)$p->prepare('UPDATE enrollments SET class=?,section=?,roll_no=? WHERE id=?')->execute([$en['class'],$en['section'],$en['roll_no'],$eid]);else $p->prepare('INSERT INTO enrollments(student_id,academic_session,class,section,roll_no) VALUES(?,?,?,?,?)')->execute(array_values($en));
