 }catch(Throwable $e){if($p->inTransaction())$p->rollBack();out(['ok'=>false,'error'=>str_contains($e->getMessage(),'UNIQUE')?'A student ID or roll number conflicts with an existing record.':$e->getMessage()],422);}}
