if($a==='class_results'){ $session=trim((string)($b['academic_session']??''));$class=trim((string)($b['class']??''));$section=trim((string)($b['section']??''));$exam=trim((string)($b['exam']??''));$subject=trim((string)($b['subject']??'')); try{groupFor($class);}catch(Throwable){out(['ok'=>false,'error'=>'Invalid class'],422);}if(!in_array($session,$GLOBALS['cfg']->sessions,true)||!in_array($exam,$GLOBALS['cfg']->exams,true)||!in_array($subject,subjectNames($class),true))out(['ok'=>false,'error'=>'Invalid session, exam or subject'],422);$q=$p->prepare('SELECT s.student_id,s.student_name,e.roll_no,r.marks_obtained,r.max_marks FROM enrollments e JOIN students s ON s.student_id=e.student_id LEFT JOIN results r ON r.student_id=e.student_id AND r.academic_session=e.academic_session AND r.exam=? AND r.subject=? WHERE e.academic_session=? AND e.class=? AND e.section=? ORDER BY CAST(e.roll_no AS INTEGER),e.roll_no,s.student_name');$q->execute([$exam,$subject,$session,$class,$section]);out(['ok'=>true,'rows'=>$q->fetchAll(),'max_marks'=>$GLOBALS['cfg']->max->$exam??20]);}
