.header-line{display:flex;align-items:center;justify-content:space-between;gap:14px}.session-pill{border:1px solid #b8c4d6;border-radius:999px;padding:8px 12px;background:#fff;color:#101828;display:flex;align-items:center;gap:8px;cursor:pointer;white-space:nowrap}.session-pill span{font-size:12px;color:#667085}.session-pill strong{font-size:14px}.data-tools{position:relative}.data-tools summary{list-style:none;cursor:pointer}.data-tools summary::-webkit-details-marker{display:none}.data-tools summary{display:inline-flex;align-items:center;gap:8px}.data-tools summary:after{content:"⌄";font-size:15px}.data-tools[open] summary:after{content:"⌃"}.data-tools-menu{max-height:70vh;overflow:auto}.same-max-control{display:flex;align-items:center;gap:9px;padding:10px 12px;border:1px solid #dbe3ef;border-radius:8px;background:#f8faff;font-weight:600}.same-max-control input{width:18px;height:18px;accent-color:#2857d8}.enrollment-state{display:grid;gap:4px;min-width:120px}.enrollment-state small{color:#667085}.status-pill.status-not-enrolled{background:#fff4e5;color:#9a4d00}.enroll-btn{padding:6px 10px;background:#2857d8;color:white;border:0;border-radius:7px;font-weight:700;cursor:pointer}.data-tools-menu{position:absolute;right:0;top:calc(100% + 5px);z-index:5;min-width:190px;padding:6px;background:#fff;border:1px solid #d0d5dd;border-radius:8px;box-shadow:0 8px 24px #10182820;display:grid;gap:2px}.data-tools-menu a{padding:9px;border-radius:6px;text-decoration:none;color:#344054}.data-tools-menu a:hover{background:#f2f4f7}.toast{position:fixed;top:12px;left:50%;transform:translateX(-50%);width:min(720px,calc(100% - 24px));z-index:1000;padding:12px 16px;display:flex;align-items:flex-start;justify-content:space-between;gap:12px;border-radius:10px;box-shadow:0 8px 28px #10182830;background:#eff8ff;color:#175cd3;border:1px solid #b2ddff;max-height:35vh;overflow:auto}.toast-close{border:0;background:transparent;color:inherit;font-size:22px;line-height:1;cursor:pointer;flex:0 0 aut