ia(max-width:600px){.header-line{align-items:flex-start;flex-direction:column}.session-pill{width:100%;justify-content:space-between}.student-list-tools{flex-direction:column;align-items:stretch}.student-list-tools select{max-width:none;width:100%}.data-tools-menu{right:auto;left:0}.toast{top:8px;width:calc(100% - 16px);max-height:40vh}.row-actions .btn{padding:6px 8px;font-size:12px}}
</style></head><body><header><div class="header-line"><div><h1>School Data Importer</h1><p>CSV / Excel → editable preview → column mapping → SQLite</p></div><button class="session-pill" id="openSessionPicker" type="button"><span>Academic session</span><strong id="currentSessionLabel">2026–2027</strong><span aria-hidden="true">▾</span></button></div></header><main>
<div class="tabs"><button class="tab active" data-kind="students">Students</button><button class="tab" data-kind="enrollments">Enrollment</button><button class="tab" data-kind="results">Result</button></div>
<section class="panel"><div class="row" style="justify-content:space-between"><div><h2 style="font-size:18px;margin:0">Import records</h2><p class="muted">CSV / Excel with editable preview and column mapping.</p></div><div class="right"><details class="data-tools"><summary class="btn">Data tools</summary><div class="data-tools-menu"><a href="?sample=students">Download Students sample CSV</a><a href="?sample=enrollments">Download Enrollment sample CSV</a><a href="?sample=results">Download Results sample CSV</a><a href="?export=students">Export Students CSV</a><a href="?export=enrollments">Export Enrollment CSV</a><a href="?export=results">Export Results CSV</a></div></details></div></div><div class="steps"><span class="step active" id="s1">1. Upload & edit</span><span class="step" id="s2">2. Map columns & import</span></div>
<div id="uploadStep"><div class="row"><div class="field" style="flex:1"><label>Choose CSV or Excel file</label><input id="file" type="file" accept=".csv,.xlsx,.xls"></div><div class="field" style="flex:1"><label>Worksheet</label><select id="sheet" disabled><option>Select file first</option></select></div></div><p class="muted">Edit the preview before mapping. Column widths follow their content.</p><div id="preview"></div><div class="actions"><label class="muted"><input id="overwrite" type="checkbox"> Update existing matching records</label><div class="right"><button class="btn" id="clear">Clear</button><button class="btn primary" id="nextMap" disabled>Next: Map →</button></div></div></div>
<div id="mapStep" class="hidden"><p class="muted">Uncheck fields you do not want to map. Disabled fields will not be imported.</p><div id="mapping" class="mapping"></div><div class="actions"><button class="btn" id="backPreview">← Back</button><button class="btn primary" id="nextConfirm">Import selected rows</button></div></div>
<div id="message" class="toast hidden" role="status" aria-live="polite" aria-atomic="true"></div></section>
<section class="panel" id="manualPanel"><div class="row" style="justify-content:space-between"><div><h2 style="font-size:18px;margin:0">Manual entry</h2><p class="muted">Add a student and first enrollment together. Use the grid for bulk records.</p></div><div class="right"><button class="btn primary" id="addStudentBtn">＋ Add Student + Enrollment</button><div class="modes"><button class="mode active" data-mode="single">Single entry</button><button class="mode" data-mode="bulk">Bulk entry</button></div></div></div>
<div id="single"><form id="form"><div id="formFields" class="formgrid"></div><p id="schoolNameNote" class="muted"></p><div class="actions"><span class="muted">* Required fields</span><div class="right"><button class="btn" type="reset">Reset</button><button class="btn primary" type="submit">Save record</button></div></div></form></div>
<div id="bulk" class="hidden"><p class="muted">One entry row is ready. Use “Add row” for additional students; use Tab to move through fields, then save.</p><div id="bulkGrid"></div><div class="actions"><button class="btn" id="addRow">+ Add row</button><button class="btn primary" id="saveBulk">Save bulk entries</button></div></div></section>
<section class="panel" id="resultWorkspace"><div class="row" style="justify-content:space-between"><div><h2 style="font-size:18px;margin:0">Result Entry</h2><p class="muted">Choose a workflow. Blank marks remain untouched.</p></div></div><div class="modes" id="resultModes"><button class="mode active" data-result-mode="one">Class-wise · Single subject</button><button class="mode" data-result-mode="all">Class-wise · All subjects</button><button class="mode" data-result-mode="student">Student-wise · All subjects</button></div><div class="formgrid" id="resultFilters"><input id="rSession" type="hidden" value="2026-2027"><div class="field"><label>Academic session</label><input id="rSessionDisplay" readonly value="2026–2027"></div><div class="field"><label>Class</label><select id="rClass"></select></div><div class="field"><label>Section</label><select id="rSection"></select></div><div class="field"><label>Exam</label><select id="rExam"></select></div><div class="field" id="rSubjectField"><label>Subject</label><select id="rSubject"></select></div><div class="field" id="rMaxField"><label>Maximum marks</label><input id="rMax" type="number" min="1" step="any"></div></div><div id="allMaxSettings" class="hidden"><label class="same-max-control"><input type="checkbox" id="sameMaxForAll" checked> Same maximum marks for all subjects</label><div class="field" id="sharedMaxField" style="margin-top:8px"><label for="sharedMax">Maximum marks (all subjects)</label><input id="sharedMax" type="number" min="1" step="any" value="20"></div></div><div id="allMaxFields" class="formgrid hidden" aria-label="Maximum marks by subject"></div><div class="actions"><button class="btn" id="loadClassResults">Refresh results (optional)</button><button class="btn primary" id="saveClassResults">Save marks</button></div><div id="classResultsGrid"></div><div id="allSubjectsGrid" class="hidden"></div><div id="studentResultFilters" class="formgrid hidden"><div class="field"><label>Student</label><select id="rsStudent"></select></div></div><div id="studentResultsGrid" class="hidden"></div></section>
<section class="panel"><div class="row" style="justify-content:space-between"><div><h2 id="recordsTitle" style="font-size:18px;margin:0">Records</h2><p id="recordsSubtitle" class="muted">Records for the selected session where applicable.</p></div><button class="btn" id="refresh">Refresh</button></div><div id="studentListTools" class="student-list-tools hidden"><input id="studentSearch" type="search" placeholder="Search ID, student or parent name" aria-label="Search students"><select id="studentStatusFilter" aria-label="Filter student status"><option value="Active">Active students</option><option value="Passed Out">Passed Out</option><option value="Withdrawn">Withdrawn</option><option value="On Hold">On Hold</option><option value="Needs review">Needs review</option><option value="all">All students</option></select></div><div id="records"></div></section></main><section id="sessionSelectionPage" class="session-page hidden" aria-labelledby="sessionPageTitle"><div class="session-page-card"><div class="row" style="justify-content:space-between;align-items:center"><div><h2 id="sessionPageTitle">Select academic session</h2><p class="muted">Only the current session and past sessions with records are shown.</p></div><button class="btn" id="closeSessionPicker" type="button">Back</button></div><div id="sessionOptions" class="session-options"></div></div></section>
<div id="studentModal" class="modal hidden"><div class="modalbox"><div class="row" style="justify-content:space-between;align-items:center"><h3 id="studentModalTitle">Add Student + Enrollment</h3><button class="btn" type="button" id="closeStudentModal">Close</button></div><form id="studentEnrollmentForm"><h4>Personal details</h4><div class="formgrid"><div class="field"><label>Student ID *</label><input name="student_id" required></div><div class="field"><label>Student name *</label><input name="student_name" required></div><div class="field"><label>Father's name</label><input name="father_name"></div><div class="field"><label>Mother's name</label><input name="mother_name"></div><div class="field"><label>Date of birth</label><input name="dob" type="date"></div><div class="field"><label>Gender *</label><select name="gender" required><option>Male</option><option>Female</option><option>Other</option></select></div><div class="field"><label>Student Status *</label><select name="status" required><option value="">Select status</option><option>Active</option><option>Passed Out</option><option>Withdrawn</option><option>On Hold</option><option>Needs review</option></select></div></div><div id="initialEnrollmentFields"><h4>Initial enrollment</h4><div class="formgrid"><div class="field"><label>Academic session *</label><input name="academic_session" id="seSession" readonly required><small class="muted">Change session from the header.</small></div><div class="field"><label>Class *</label><select name="class" id="seClass" required></select></div><div class="field"><label>Section *</label><select name="section" id="seSection"></select></div><div class="field"><label>Roll number</label><input name="roll_no" inputmode="numeric"><small class="muted">Optional until assigned.</small></div></div><p class="muted" id="seSchoolNote"></p></div><p class="muted" id="studentSaveNote">Student details and initial enrollment are saved together.</p><div class="actions"><button class="btn" type="button" id="cancelStudentModal">Cancel</button><button class="btn primary" type="submit">Save Student + Enrollment</button></div></form></div></div>
<div id="modal" class="modal hidden"><div class="modalbox cropper-box"><div class="row" style="justify-content:space-between;align-items:center"><h3>Student photo</h3><button class="btn" id="cancelPhoto">Cancel</button></div><p class="muted" id="cropInfo"></p><div class="actions" style="justify-content:flex-start"><button class="btn" id="replacePhoto" type="button">Select New Photo</button></div><input type="file" id="photoFile" accept="image/jpeg,image/png,image/webp" class="hidden"><div class="cropper-viewport"><img id="cropImage" alt="Crop photo" class="hidden"></div><div class="actions"><button class="btn" id="cancelCrop" type="button">Cancel</button><button class="btn primary" id="savePhoto" type="button">Apply Crop and Save</button></div><p id="photoMsg" class="muted"></p></div></div>
<script>
const C=<?=json_encode($publicCfg,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>, S=<?=json_encode($schema,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
let kind='students',mode='bulk',studentEdit=false,wb=null,headers=[],rows=[],mapped=[],selectedImportRows=[],invalidImportRows=[],edit=null,bulkRows=[],bulkTouched=[],cropper=null,photoId='';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),norm=s=>String(s??'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
let toastTimer;function message(t,type='notice'){const el=$('message');el.className='toast '+type;el.replaceChildren();const text=document.createElement('span');text.textContent=t;const close=document.createElement('button');close.type='button';close.className='toast-close';close.setAttribute('aria-label','Dismiss notification');close.textContent='×';close.onclick=()=>el.classList.add('hidden');el.append(text,close);el.classList.remove('hidden');el.setAttribute('role',type==='error'?'alert':'status');clearTimeout(toastTimer);if(type==='success'||type==='notice')toastTimer=setTimeout(()=>el.classList.add('hidden'),6500)}
function group(c){return ['1','2','3'].includes(String(c))?'primary':['4','5','6','7','8'].includes(String(c))?'middle':'secondary'}
function subjects(c){return C.groups[group(c)].map(k=>C.subjects[k])}
function defaults(){return {academic_session:C.session,section:'A',class:'1',gender:'Male',status:'Active',exam:'PA-I',subject:'Hindi',max_marks:C.max['PA-I']}}
function input(f,v='',idx=null){let name=f.name,id='f_'+name,req=f.required?'required':'';if(f.type==='gender')return `<div class="field"><label>${f.label} *</label><div class="radio">${['Male','Female','Other'].map(x=>`<label><input type="radio" name="${name}" value="${x}" ${v===x?'checked':''} ${req}>${x}</label>`).join('')}</div></div>`;
let options=f.type==='status'?['Active','Passed Out','Withdrawn','On Hold','Needs review']:f.type==='session'?C.sessions:f.type==='section'?C.sections:f.type==='class'?C.classes:f.type==='exam'?C.exams:f.type==='subject'?subjects(edit?.class||document.querySelector('[name=class]')?.value||v||'1'):null;
if(f.type==='session')return `<div class="field"><label>${f.label}${f.required?' *':''}</label><input name="${name}" id="${id}" value="${esc(C.session)}" readonly required></div>`;if(options)return `<div class="field"><label>${f.label}${f.required?' *':''}</label><select name="${name}" id="${id}" ${req}>${options.map(x=>`<option value="${esc(x)}" ${String(v)===String(x)?'selected':''}>${f.type==='class'?'Class '+x:esc(x)}</option>`).join('')}</select></div>`;
return `<div class="field"><label>${f.label}${f.required?' *':''}</label><input name="${name}" id="${id}" type="${f.type==='number'?'number':f.type==='date'?'date':'text'}" ${f.type==='number'?'step="any" min="0"':''} value="${esc(v)}" ${req}></div>`}
function renderForm(){let d=defaults();$('formFields').innerHTML=S[kind].map(f=>input(f,edit?.[f.name]??d[f.name]??'')).join('');const c=$('form').elements.class,e=$('form').elements.exam;const updateSchool=()=>{const cl=c?.value||'1';$('schoolNameNote').textContent='School name for Class '+cl+': '+(Number(cl)>=9?C.schools.secondary:C.schools.primary)};updateSchool();if(c)c.onchange=()=>{updateSchool();let s=$('form').elements.subject;if(s){let old=s.value;s.innerHTML=subjects(c.value).map(x=>`<option>${esc(x)}</option>`).join('');if(subjects(c.value).includes(old))s.value=old}};if(e)e.onchange=()=>{if($('form').elements.max_marks)$('form').elements.max_marks.value=C.max[e.value]??80};$('form').querySelector('[type=submit]').textContent=edit?'Update record':'Save record'}
function step(n){const stepNo=Math.max(1,Math.min(n,2));['uploadStep','mapStep'].forEach((x,i)=>$(x).classList.toggle('hidden',i!==stepNo-1));['s1','s2'].forEach((x,i)=>$(x).classList.toggle('active',i===stepNo-1))}
function resetImport(){wb=null;headers=[];rows=[];mapped=[];selectedImportRows=[];invalidImportRows=[];$('file').value='';$('sheet').innerHTML='<option>Select file first</option>';$('sheet').disabled=true;$('preview').innerHTML='';$('mapping').innerHTML='';$('nextMap').disabled=true;step(1)}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{kind=b.dataset.kind;edit=null;$('resultWorkspace').classList.toggle('hidden',kind!=='results');$('manualPanel').classList.toggle('hidden',kind==='results');document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===b));const singleBtn=document.querySelector('.mode[data-mode="single"]');if(kind==='students'){singleBtn.classList.add('hidden');mode='bulk';$('single').classList.add('hidden');$('bulk').classList.remove('hidden');document.querySelectorAll('.mode').forEach(x=>x.classList.toggle('active',x.dataset.mode==='bulk'));}else{singleBtn.classList.remove('hidden');mode='single';$('single').classList.remove('hidden');$('bulk').classList.add('hidden');document.querySelectorAll('.mode').forEach(x=>x.classList.toggle('active',x.dataset.mode==='single'));}resetImport();renderForm();bulkRows=[bulkDefaults()];bulkTouched=[false];renderBulk();loadRecords();if(kind==='results')setResultMode('one')});
document.querySelectorAll('.mode').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('.mode').forEach(x=>x.classList.toggle('active',x===b));$('single').classList.toggle('hidden',mode!=='single');$('bulk').classList.toggle('hidden',mode!=='bulk');if(mode==='bulk')renderBulk()});
$('file').onchange=async e=>{if(!e.target.files[0])return;try{wb=XLSX.read(await e.target.files[0].arrayBuffer(),{type:'array'});$('sheet').innerHTML=wb.SheetNames.map(x=>`<option>${esc(x)}</option>`).join('');$('sheet').disabled=wb.SheetNames.length<2;readSheet(wb.SheetNames[0])}catch(err){message('Could not read file: '+err.message,'error')}};
$('sheet').onchange=()=>wb&&readSheet($('sheet').value);
function readSheet(n){let data=XLSX.utils.sheet_to_json(wb.Sheets[n],{header:1,defval:'',raw:false});if(!data.length)return;headers=data[0].map((x,i)=>String(x||`Column ${i+1}`));rows=data.slice(1).filter(r=>r.some(x=>String(x??'').trim())).map(r=>headers.map((_,i)=>String(r[i]??'')));selectedImportRows=rows.map(()=>true);renderPreview();$('nextMap').disabled=!rows.length;message(`${rows.length} rows loaded. Edit before mapping.`,'success')}
function renderPreview(){const selectable=true;$('preview').innerHTML='<div class="gridwrap"><table><thead><tr>'+(selectable?`<th><label style="display:flex;gap:5px;align-items:center"><input id="selectAllImport" type="checkbox" ${selectedImportRows.length&&selectedImportRows.every(Boolean)?'checked':''}> Select All</label></th>`:'')+headers.map(x=>`<th>${esc(x)}</th>`).join('')+'</tr></thead><tbody>'+rows.map((r,i)=>'<tr class="'+(invalidImportRows.includes(i)?'import-row-invalid':'')+'">'+(selectable?`<td><input type="checkbox" class="import-row-check" data-select-row="${i}" aria-label="Select import row ${i+1}" ${selectedImportRows[i]?'checked':''}></td>`:'')+r.map((v,j)=>`<td><input data-r="${i}" data-c="${j}" value="${esc(v)}"></td>`).join('')+'</tr>').join('')+'</tbody></table></div>'; $('preview').querySelectorAll('input[data-r]').forEach(x=>x.oninput=()=>{const i=+x.dataset.r;rows[i][+x.dataset.c]=x.value;invalidImportRows=invalidImportRows.filter(n=>n!==i);x.closest('tr')?.classList.remove('import-row-invalid')});$('preview').querySelectorAll('[data-select-row]').forEach(x=>x.onchange=()=>{selectedImportRows[+x.dataset.selectRow]=x.checked;const a=$('selectAllImport');if(a)a.checked=selectedImportRows.length>0&&selectedImportRows.every(Boolean);});const all=$('selectAllImport');if(all)all.onchange=()=>{selectedImportRows=rows.map(()=>all.checked);$('preview').querySelectorAll('[data-select-row]').forEach(x=>x.checked=all.checked)}}
$('clear').onclick=resetImport;$('nextMap').onclick=()=>{renderMapping();step(2)};$('backPreview').onclick=()=>step(1);
function match(f){let candidates=[f.label,f.name,...f.aliases].map(norm),best=0,idx='';headers.forEach((h,i)=>{let n=norm(h),score=candidates.includes(n)?100:candidates.some(x=>x&&n&&(n.includes(x)||x.includes(n)))?50:0;if(score>best){best=score;idx=String(i)}});return best>=50?idx:''}
function renderMapping(){$('mapping').innerHTML=S[kind].map(f=>{let idx=match(f);return `<div class="mapitem ${idx===''&&!f.required?'disabled':''}" data-f="${f.name}"><label><input class="enabled" type="checkbox" ${idx!==''||f.required?'checked':''}>${esc(f.label)}${f.required?' *':''}</label><select class="source" ${idx===''?'disabled':''}><option value="">— Do not map —</option>${headers.map((h,i)=>`<option value="${i}" ${String(i)===idx?'selected':''}>${esc(h)}</option>`).join('')}</select></div>`}).join('');$('mapping').querySelectorAll('.enabled').forEach(ch=>ch.onchange=()=>{let box=ch.closest('.mapitem'),sel=box.querySelector('.source');sel.disabled=!ch.checked;box.classList.toggle('disabled',!ch.checked)})}
$('nextConfirm').onclick=async()=>{let map={},bad=[];$('mapping').querySelectorAll('.mapitem').forEach(box=>{let f=box.dataset.f,meta=S[kind].find(x=>x.name===f),sel=box.querySelector('.source');map[f]=box.querySelector('.enabled').checked&&sel.value!==''?+sel.value:null;if(meta.required&&map[f]===null&&!(kind!=='students'&&f==='academic_session'))bad.push(meta.label)});if(bad.length){message('Map required fields: '+bad.join(', '),'error');return}mapped=rows.map((r,i)=>({r,i})).filter(({i})=>selectedImportRows[i]!==false).map(({r,i})=>{const out=Object.fromEntries(Object.entries(map).filter(([k,v])=>v!==null).map(([k,v])=>[k,r[v]??'']));out.__sourceIndex=i;if(kind!=='students')out.academic_session=C.session;return out});if(!mapped.length){message('Select at least one row to import.','error');return}const requiredFields=S[kind].filter(f=>f.required&&!(kind!=='students'&&f.name==='academic_session'));const rowErrors=[];invalidImportRows=[];mapped.forEach((row,i)=>{for(const f of requiredFields)if(String(row[f.name]??'').trim()===''){rowErrors.push('Selected row '+(i+1)+': '+f.label+' is required.');invalidImportRows.push(row.__sourceIndex);break}});if(rowErrors.length){renderPreview();message('Some selected rows have missing required values. Invalid rows are highlighted. '+rowErrors.slice(0,5).join(' | '),'warning');if(!confirm(`${invalidImportRows.length} selected row(s) have missing required values. Import only the valid rows and skip the highlighted rows? Choose Cancel to return to the preview and correct them.`)){step(1);return}mapped=mapped.filter(row=>!invalidImportRows.includes(row.__sourceIndex));if(!mapped.length){step(1);message('No valid selected rows remain. Correct the highlighted rows before importing.','error');return}}mapped=mapped.map(({__sourceIndex,...row})=>row);const btn=$('nextConfirm');btn.disabled=true;try{const d=await api({action:'save',kind,rows:mapped,overwrite:$('overwrite').checked}),r=d.result;message(`Import complete: inserted ${r.inserted}; updated ${r.updated}; skipped ${r.skipped}. `+(r.errors||[]).slice(0,8).join(' | '),(r.errors?.length||r.skipped>0)?((r.inserted+r.updated)>0||r.skipped>0?'warning':'error'):'success');resetImport();loadRecords()}catch(e){message(e.message,'error')}finally{btn.disabled=false}};
async function api(x){let r=await fetch('?api=1',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(x)}),d=await r.json();if(!r.ok||!d.ok)throw Error(d.error||'Request failed');return d}
function sessionLabel(s){return String(s).replace('-', '–')}
function renderSessionOptions(){ $('currentSessionLabel').textContent=sessionLabel(C.session);$('rSession').value=C.session;$('rSessionDisplay').value=sessionLabel(C.session);$('sessionOptions').innerHTML=C.sessions.map(s=>`<button type="button" class="session-option ${s===C.session?'selected':''}" data-session="${esc(s)}"><span class="session-radio">${s===C.session?'●':'○'}</span><span><strong>${esc(sessionLabel(s))}</strong><small>${s===C.currentSession?'Current academic session':s===C.session?'Selected session':'Past session with records'}</small></span></button>`).join('');$('sessionOptions').querySelectorAll('[data-session]').forEach(b=>b.onclick=async()=>{try{const d=await api({action:'set_session',academic_session:b.dataset.session});C.session=d.session;C.sessions=d.sessions;renderSessionOptions();$('classResultsGrid').innerHTML='';$('allSubjectsGrid').innerHTML='';$('studentResultsGrid').innerHTML='';if($('form').elements.academic_session)$('form').elements.academic_session.value=C.session;$('seSession').value=C.session;bulkRows=bulkRows.map(r=>({...r,academic_session:C.session}));if(mode==='bulk')renderBulk();$('sessionSelectionPage').classList.add('hidden');loadRecords();if(!$('resultWorkspace').classList.contains('hidden')){if(resultMode==='one')$('loadClassResults').click();else loadGridResults()}message('Academic session changed to '+sessionLabel(C.session)+'.','success')}catch(e){message(e.message,'error')}})}
$('openSessionPicker').onclick=()=>{$('sessionSelectionPage').classList.remove('hidden');renderSessionOptions()};$('closeSessionPicker').onclick=()=>$('sessionSelectionPage').classList.add('hidden');
$('form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,row=Object.fromEntries(new FormData(form));try{let d;if(edit&&kind!=='students'){d=await api({action:'update_record',kind,id:edit.id,row});}else{d=await api({action:'save',kind,rows:[row],overwrite:true});const r=d.result;if(r.errors.length)throw Error(r.errors.join(' | '));}const savedKind=kind;edit=null;form.reset();renderForm();if(savedKind==='results'){$('manualPanel').classList.add('hidden');$('resultWorkspace').classList.remove('hidden')}message('Record saved.','success');loadRecords()}catch(err){message(err.message,'error')}};
$('form').onreset=()=>setTimeout(()=>{if(!edit)renderForm()},0);
function bulkFields(){return kind==='students'?[...S.students,{name:'academic_session',label:'Academic Session',required:true,type:'session'},{name:'class',label:'Class',required:true,type:'class'},{name:'section',label:'Section',required:true,type:'section'},{name:'roll_no',label:'Roll No.',required:false,type:'text'}]:S[kind]}
function bulkDefaults(){let d=defaults();if(kind==='students'){d.academic_session=C.session;d.class='1';d.section='A';d.roll_no=''}return Object.fromEntries(bulkFields().map(f=>[f.name,d[f.name]??'']))}
function rowHasData(r,i){const has=(k)=>String(r[k]??'').trim()!=='';if(kind==='students')return ['student_id','student_name','father_name','mother_name','dob','roll_no'].some(has)||String(r.gender||'Male')!=='Male'||String(r.status||'Active')!=='Active'||String(r.class||'1')!=='1'||String(r.section||'A')!=='A';if(kind==='enrollments')return has('student_id')||String(r.class||'1')!=='1'||String(r.section||'A')!=='A'||has('roll_no');return has('student_id')||has('marks_obtained')||String(r.class||'1')!=='1'||String(r.exam||'PA-I')!=='PA-I'||String(r.subject||'Hindi')!=='Hindi'||String(r.max_marks||'20')!=='20'}
function bulkInput(f,r,i){let id=`bulk-${i}-${f.name}`;if(f.type==='session')return `<div class="field"><label for="${id}">${esc(f.label)}${f.required?' *':''}</label><input id="${id}" data-r="${i}" data-f="${f.name}" value="${esc(C.session)}" readonly required></div>`;let opts=f.type==='status'?['Active','Passed Out','Withdrawn','On Hold','Needs review']:f.type==='session'?C.sessions:f.type==='section'?C.sections:f.type==='class'?C.classes:f.type==='exam'?C.exams:f.type==='gender'?['Male','Female','Other']:f.type==='subject'?subjects(r.class||'1'):null;let value=String(r[f.name]??'');return `<div class="field"><label for="${id}">${esc(f.label)}${f.required?' *':''}</label>${opts?`<select id="${id}" data-r="${i}" data-f="${f.name}" ${f.required?'required':''}>${opts.map(x=>`<option value="${esc(x)}" ${value===String(x)?'selected':''}>${esc(f.type==='class'?'Class '+x:x)}</option>`).join('')}</select>`:`<input id="${id}" data-r="${i}" data-f="${f.name}" type="${f.type==='date'?'date':f.type==='number'?'number':'text'}" value="${esc(value)}" ${f.required?'required':''} ${f.type==='number'?'step="any" min="0"':''}>`}</div>`}
function renderBulk(focusKey=null){const host=$('bulkGrid');if(kind==='students'){host.innerHTML=bulkRows.length?'<div class="bulk-student-list">'+bulkRows.map((r,i)=>`<section class="bulk-student-card" aria-labelledby="bulk-title-${i}"><div class="bulk-student-card-header"><h3 id="bulk-title-${i}">Student ${i+1}${rowHasData(r)?'':' — New entry'}</h3>${i>0?`<button type="button" class="btn remove-row" data-remove="${i}" aria-label="Remove student row ${i+1}">Remove row</button>`:''}</div><div class="bulk-student-fields-scroll"><div class="formgrid">${bulkFields().map(f=>bulkInput(f,r,i)).join('')}</div></div></section>`).join('')+'</div>':'<p class="muted">No rows yet. Select “Add row” to create a student entry.</p>'}else{host.innerHTML='<div class="gridwrap"><table><thead><tr>'+bulkFields().map(f=>`<th scope="col">${esc(f.label)}${f.required?' *':''}</th>`).join('')+'<th>Action</th></tr></thead><tbody>'+bulkRows.map((r,i)=>'<tr>'+bulkFields().map(f=>`<td>${bulkInput(f,r,i)}</td>`).join('')+`<td>${i>0?`<button type="button" class="btn remove-row" data-remove="${i}">Remove row</button>`:''}</td></tr>`).join('')+'</tbody></table></div>'}
 host.querySelectorAll('[data-r]').forEach(el=>{el.addEventListener('input',()=>{const i=Number(el.dataset.r),f=el.dataset.f;if(bulkRows[i])bulkRows[i][f]=el.value;bulkTouched[i]=true});el.addEventListener('change',()=>{const i=Number(el.dataset.r),f=el.dataset.f;if(!bulkRows[i])return;bulkRows[i][f]=el.value;bulkTouched[i]=true;if(f==='exam'&&kind==='results')bulkRows[i].max_marks=C.max[el.value]??80;if(f==='class'&&kind==='results'&&!subjects(el.value).includes(bulkRows[i].subject)){bulkRows[i].subject=subjects(el.value)[0];renderBulk(`${i}-${f}`)}})});
 host.onclick=e=>{const btn=e.target.closest('[data-remove]');if(!btn||!host.contains(btn))return;const i=Number(btn.dataset.remove);if(!Number.isInteger(i)||i<=0||i>=bulkRows.length)return;const row=bulkRows[i]||{};const hasData=rowHasData(row,i);if(hasData&&!confirm('This row contains data. Remove it?'))return;bulkRows.splice(i,1);bulkTouched.splice(i,1);renderBulk();const focusTarget=host.querySelector(`[data-r="${Math.min(i,bulkRows.length-1)}"]`)||$('addRow');focusTarget?.focus({preventScroll:true});};
 if(focusKey){const [i,f]=focusKey.split('-');host.querySelector(`[data-r="${i}"][data-f="${f}"]`)?.focus({preventScroll:true})}}
$('addRow').onclick=()=>{bulkRows.push(bulkDefaults());bulkTouched.push(false);renderBulk();const last=bulkRows.length-1;$('bulkGrid').querySelector(`[data-r="${last}"]`)?.focus()};$('saveBulk').onclick=async()=>{let data=bulkRows.filter(rowHasData);if(!data.length){message('Enter at least one record.','error');return}const btn=$('saveBulk');btn.disabled=true;try{let d=kind==='students'?await api({action:'bulk_save_student_enrollments',rows:data}):await api({action:'save',kind,rows:data,overwrite:true}),r=d.result;message(`Bulk save: inserted ${r.inserted}, updated ${r.updated}, skipped ${r.skipped}. `+(r.errors||[]).slice(0,8).join(' | '),(r.errors?.length||r.skipped>0)?((r.inserted+r.updated)>0||r.skipped>0?'warning':'error'):'success');if(!r.errors?.length){bulkRows=[bulkDefaults()];bulkTouched=[false];renderBulk()}if(r.inserted+r.updated>0)loadRecords()}catch(e){message(e.message,'error')}finally{btn.disabled=false}};
async function loadRecords(){try{const status=kind==='students'?($('studentStatusFilter')?.value||'Active'):'',search=kind==='students'?($('studentSearch')?.value||''):'';let data=await(await fetch('?list='+kind+'&session='+encodeURIComponent(C.session)+'&status='+encodeURIComponent(status)+'&search='+encodeURIComponent(search)+'&_='+Date.now(),{cache:'no-store'})).json(),fs=S[kind];$('studentListTools').classList.toggle('hidden',kind!=='students');$('recordsTitle').textContent=kind==='students'?'Students':kind==='enrollments'?'Enrollment records':'Result records';$('recordsSubtitle').textContent=kind==='students'?'Permanent student details · '+($('studentStatusFilter')?.selectedOptions[0]?.textContent||'Active'):'Academic session '+sessionLabel(C.session);if(kind==='results'){const groups=new Map();for(const r of data.rows){const key=[r.student_id,r.academic_session,r.exam,r.class||'',r.section||''].join('|');if(!groups.has(key))groups.set(key,{...r,subjects:{},ids:[]});const g=groups.get(key);g.subjects[r.subject]={marks:r.marks_obtained,max:r.max_marks};g.ids.push(r.id)}data.rows=[...groups.values()]}let html='<div class="gridwrap"><table><thead><tr>'+(kind==='students'?'<th>Photo</th><th>Student ID</th><th>Name</th><th>Father&#39;s Name</th><th>Mother&#39;s Name</th><th>DOB</th><th>Gender</th><th>Status</th><th>Enrollment</th>':kind==='enrollments'?'<th>Student ID</th><th>Academic Session</th><th>Class</th><th>Section</th><th>Roll No.</th>':'<th>Student</th><th>Student ID</th><th>Exam</th><th>Class</th><th>Section</th><th>Roll No.</th><th>Subject marks</th>')+'<th>Actions</th></tr></thead><tbody>';if(!data.rows.length)html+='<tr><td colspan="12">No records match this view.</td></tr>';data.rows.forEach(r=>{html+='<tr>';if(kind==='students'){html+=`<td><button type="button" class="photo" aria-label="${r.photo_path?'Edit student photo':'Upload student photo'}" onclick="openPhoto('${esc(r.student_id)}',${r.photo_path?'true':'false'})">${r.photo_path?`<img src="${esc(r.photo_path)}?v=${Date.now()}" alt="Student photo">`:'<span class="photo-label"><span>Upload</span><span>Photo</span></span>'}</button></td><td>${esc(r.student_id)}</td><td>${esc(r.student_name)}</td><td>${esc(r.father_name||'—')}</td><td>${esc(r.mother_name||'—')}</td><td>${esc(r.dob||'—')}</td><td>${esc(r.gender||'—')}</td><td><span class="status-pill status-${norm(r.status||'Needs review')}">${esc(r.status||'Needs review')}</span></td><td>${r.enrolled?`<div class="enrollment-state"><span class="status-pill">Enrolled</span><small>Class ${esc(r.enrolled_class)} · ${esc(r.enrolled_section||'—')}${r.enrolled_roll?` · Roll ${esc(r.enrolled_roll)}`:''}</small></div>`:`<div class="enrollment-state"><span class="status-pill status-not-enrolled">Not enrolled</span><button type="button" class="enroll-btn" onclick="enrollStudent('${esc(r.student_id)}')">Enroll</button></div>`}</td>`}else if(kind==='enrollments'){html+=`<td>${esc(r.student_id)}</td><td>${esc(r.academic_session)}</td><td>Class ${esc(r.class)}</td><td>${esc(r.section)}</td><td>${esc(r.roll_no||'—')}</td>`}else{html+=`<td>${esc(r.student_name||r.student_id)}</td><td>${esc(r.student_id)}</td><td>${esc(r.exam)}</td><td>${esc(r.class||'—')}</td><td>${esc(r.section||'—')}</td><td>${esc(r.roll_no||'—')}</td><td><div class="result-subject-summary">${Object.entries(r.subjects||{}).map(([sub,v])=>`<span><strong>${esc(sub)}</strong>: ${esc(v.marks)}/${esc(v.max)}</span>`).join(' · ')}</div></td>`}html+=`<td><div class="row-actions">${kind==='results'?`<button class="btn" onclick="editResultGroup('${esc(r.student_id)}','${esc(r.exam)}','${esc(r.class||'')}','${esc(r.section||'')}')">Edit marks</button> <button class="btn danger" onclick="deleteResultGroup('${esc(r.student_id)}','${esc(r.exam)}')">Delete exam marks</button>`:`<button class="btn" onclick="${kind==='students'?`editStudent('${esc(r.student_id)}')`:`editRecord(${r.id})`}">Edit</button> <button class="btn danger" onclick="deleteRecord(${r.id})">Delete</button>`}</div></td></tr>`});$('records').innerHTML=html+'</tbody></table></div>'}catch(e){$('records').textContent='Could not load records.';message('Could not load records: '+e.message,'error')}}
window.editRecord=async id=>{try{const recordKind=kind;const d=await api({action:'get',kind:recordKind,id});kind=recordKind;edit=d.row;studentEdit=false;document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.kind===kind));$('resultWorkspace').classList.add('hidden');$('manualPanel').classList.remove('hidden');document.querySelectorAll('.mode').forEach(x=>x.classList.toggle('active',x.dataset.mode==='single'));mode='single';$('single').classList.remove('hidden');$('bulk').classList.add('hidden');renderForm();Object.entries(d.row).forEach(([k,v])=>{const el=$('form').elements[k];if(el&&v!==null)el.value=v});$('form').querySelector('[type=submit]').textContent='Update record';document.querySelector('#manualPanel')?.scrollIntoView({behavior:'smooth',block:'start'});}catch(e){message(e.message,'error')}};
window.deleteRecord=async id=>{if(!confirm('Delete this record? Deleting a student also deletes linked enrollment and results.'))return;try{await api({action:'delete',kind,id});message('Deleted.','success');loadRecords()}catch(e){message(e.message,'error')}};
window.editResultGroup=(studentId,exam,cl,section)=>{setResultMode('student');$('rClass').value=cl||$('rClass').value;$('rExam').value=exam;refreshResultSubjects();renderMaxFields();$('rSection').value=section||$('rSection').value;loadGridResults().then(()=>{if($('rsStudent').querySelector(`option[value="${CSS.escape(studentId)}"]`))$('rsStudent').value=studentId;loadGridResults();$('resultWorkspace').scrollIntoView({behavior:'smooth',block:'start'})})};window.deleteResultGroup=async(studentId,exam)=>{if(!confirm(`Delete all saved subject marks for ${studentId} in ${exam} for ${sessionLabel(C.session)}? This cannot be undone.`))return;try{const d=await api({action:'delete_result_group',student_id:studentId,exam,academic_session:C.session});message(`${d.deleted} subject result(s) deleted.`,'success');loadRecords()}catch(e){message(e.message,'error')}};
let photoExistingUrl='',photoObjectUrl='',photoFromExisting=false;
function resetCropper(){
 if(cropper){cropper.destroy();cropper=null}
 if(photoObjectUrl){URL.revokeObjectURL(photoObjectUrl);photoObjectUrl=''}
 $('cropImage').onload=null;$('cropImage').removeAttribute('src');$('cropImage').classList.add('hidden');$('photoFile').value='';$('photoMsg').textContent='';$('savePhoto').classList.add('hidden');
}
function startCrop(src){
 if(cropper){cropper.destroy();cropper=null}
 $('cropImage').classList.remove('hidden');$('savePhoto').classList.remove('hidden');
 $('cropImage').onload=()=>{
  if(cropper){cropper.destroy();cropper=null}
  cropper=new Cropper($('cropImage'),{aspectRatio:C.image.width/C.image.height,viewMode:1,autoCropArea:1,responsive:true,background:false,checkOrientation:true,zoomable:true,rotatable:true,dragMode:'move'});
 };
 $('cropImage').src=src;
}
$('cropImage').addEventListener('contextmenu',e=>e.preventDefault());document.querySelector('.cropper-viewport').addEventListener('contextmenu',e=>e.preventDefault());$('cropImage').draggable=false;
function showCropModal(){
 $('modal').classList.remove('hidden');
 $('cropInfo').textContent=`Crop ratio ${C.image.width}:${C.image.height}; output ${C.image.width} × ${C.image.height} pixels.`;
}
window.openPhoto=async(id,hasPhoto=false)=>{
 photoId=id;resetCropper();photoExistingUrl='';photoFromExisting=false;
 if(!hasPhoto){
  // For a student without a photo, open the native file selector immediately.
  $('photoFile').value='';$('photoFile').click();return;
 }
 try{
  const d=await api({action:'get_photo',student_id:id});photoExistingUrl=d.photo_path||'';
  if(!photoExistingUrl){$('photoFile').value='';$('photoFile').click();return}
  photoFromExisting=true;showCropModal();$('photoMsg').textContent='Adjust the crop, or select a new photo to replace this one.';
  startCrop(photoExistingUrl+'?v='+Date.now());
 }catch(e){message(e.message,'error')}
};
$('cancelPhoto').onclick=()=>{$('modal').classList.add('hidden');resetCropper();photoExistingUrl=''};
$('cancelCrop').onclick=()=>{$('modal').classList.add('hidden');resetCropper();photoExistingUrl=''};
$('replacePhoto').onclick=()=>{$('photoFile').value='';$('photoFile').click()};
$('photoFile').onchange=e=>{
 const f=e.target.files&&e.target.files[0];if(!f)return;
 if(!/^image\/(jpeg|png|webp)$/.test(f.type)){ $('photoMsg').textContent='Choose a JPG, PNG or WebP image.';message('Choose a JPG, PNG or WebP image.','error');e.target.value='';return}
 resetCropper();photoObjectUrl=URL.createObjectURL(f);photoFromExisting=false;showCropModal();$('photoMsg').textContent='Adjust the crop, or select a different photo.';startCrop(photoObjectUrl);
};
$('savePhoto').onclick=async()=>{
 if(!cropper){$('photoMsg').textContent='Choose an image first.';message('Choose an image first.','error');return}
 try{
  const canvas=cropper.getCroppedCanvas({width:C.image.width,height:C.image.height,imageSmoothingEnabled:true,imageSmoothingQuality:'high'});
  const data=canvas.toDataURL('image/jpeg',.92);
  await api({action:'photo',student_id:photoId,data_url:data});$('modal').classList.add('hidden');resetCropper();photoExistingUrl='';message('Photo saved.','success');loadRecords();
 }catch(e){$('photoMsg').textContent=e.message;message(e.message,'error')}
};
function fillSelect(id,items,format=x=>x){$(id).innerHTML=items.map(x=>`<option value="${esc(x)}">${esc(format(x))}</option>`).join('')}
function updateSchoolNote(){let c=$('seClass').value;$('seSchoolNote').textContent='School name: '+(Number(c)>=9?C.schools.secondary:C.schools.primary)}
function openStudentForm(){studentEdit=false;const f=$('studentEnrollmentForm');f.reset();f.elements.status.value='Active';$('initialEnrollmentFields').classList.remove('hidden');f.elements.class.required=true;f.elements.section.required=true;f.elements.academic_session.required=true;$('seSession').value=C.session;fillSelect('seClass',C.classes,x=>'Class '+x);fillSelect('seSection',C.sections);$('seSection').value='A';$('studentModalTitle').textContent='Add Student + Enrollment';$('studentSaveNote').textContent='Student details and initial enrollment are saved together. Roll number can be assigned later.';f.querySelector('[type=submit]').textContent='Save Student + Enrollment';f.elements.student_id.readOnly=false;updateSchoolNote();$('studentModal').classList.remove('hidden');f.elements.student_id.focus()}
window.editStudent=async id=>{try{const d=await api({action:'get_student_enrollment',student_id:id,academic_session:C.session});studentEdit=true;const f=$('studentEnrollmentForm');f.reset();$('seSession').value=C.session;fillSelect('seClass',C.classes,x=>'Class '+x);fillSelect('seSection',C.sections);Object.entries(d.row).forEach(([k,v])=>{if(f.elements[k]&&v!==null)f.elements[k].value=v});if(d.row.status===null||!String(d.row.status).trim())f.elements.status.value='Needs review';const hasCurrentEnrollment=d.row.class!==null&&d.row.class!==undefined;$('initialEnrollmentFields').classList.toggle('hidden',!hasCurrentEnrollment);f.elements.class.required=hasCurrentEnrollment;f.elements.section.required=hasCurrentEnrollment;f.elements.academic_session.required=hasCurrentEnrollment;$('studentModalTitle').textContent=hasCurrentEnrollment?'Edit Student + Enrollment':'Edit Student Details';$('studentSaveNote').textContent=hasCurrentEnrollment?'Student details and the selected-session enrollment will be updated.':'No enrollment exists for the selected session. This form will update permanent student details only; use Enrollment to add an enrollment.';f.querySelector('[type=submit]').textContent=hasCurrentEnrollment?'Update Student + Enrollment':'Save Student Details';f.elements.student_id.readOnly=true;updateSchoolNote();$('studentModal').classList.remove('hidden')}catch(e){message(e.message,'error')}};
$('addStudentBtn').onclick=openStudentForm;$('closeStudentModal').onclick=$('cancelStudentModal').onclick=()=>$('studentModal').classList.add('hidden');$('seClass').onchange=updateSchoolNote;
window.enrollStudent=async id=>{try{const d=await api({action:'get_student_enrollment',student_id:id,academic_session:C.session});studentEdit=false;const f=$('studentEnrollmentForm');f.reset();$('seSession').value=C.session;fillSelect('seClass',C.classes,x=>'Class '+x);fillSelect('seSection',C.sections);Object.entries(d.row).forEach(([k,v])=>{if(f.elements[k]&&v!==null)f.elements[k].value=v});f.elements.student_id.readOnly=true;$('initialEnrollmentFields').classList.remove('hidden');f.elements.class.required=true;f.elements.section.required=true;f.elements.academic_session.required=true;$('studentModalTitle').textContent='Enroll Existing Student';$('studentSaveNote').textContent='Permanent student details are retained. Choose the class and section for '+sessionLabel(C.session)+'. Roll number is optional.';f.querySelector('[type=submit]').textContent='Save Enrollment';updateSchoolNote();$('studentModal').classList.remove('hidden');f.elements.class.focus()}catch(e){message(e.message,'error')}};
$('studentEnrollmentForm').onsubmit=async e=>{e.preventDefault();const btn=e.currentTarget.querySelector('[type=submit]');btn.disabled=true;try{const row=Object.fromEntries(new FormData(e.currentTarget));row.edit_existing=studentEdit;const d=await api({action:'save_student_enrollment',row});photoId=d.student_id;$('studentModal').classList.add('hidden');message('Student and enrollment saved. You can add or change the photo from the student list.','success');loadRecords();studentEdit=false;}catch(err){message(err.message,'error')}finally{btn.disabled=false}};
$('rSession').value=C.session;$('rSessionDisplay').value=sessionLabel(C.session);fillSelect('rClass',C.classes,x=>'Class '+x);fillSelect('rSection',C.sections);fillSelect('rExam',C.exams);function renderMaxFields(){const host=$('allMaxFields');if(!host)return;const subs=subjects($('rClass').value);host.innerHTML=subs.map(sub=>`<div class="field"><label>Maximum marks · ${esc(sub)}</label><input type="number" min="1" step="any" data-max-sub="${esc(sub)}" value="${esc(C.max[$('rExam').value]??20)}"></div>`).join('');host.classList.toggle('hidden',resultMode==='one'||(resultMode==='all'&&$('sameMaxForAll').checked))}function maxMarksMap(){const subs=subjects($('rClass').value);if(resultMode==='all'&&$('sameMaxForAll').checked)return Object.fromEntries(subs.map(sub=>[sub,Number($('sharedMax').value||C.max[$('rExam').value]||20)]));return Object.fromEntries([...document.querySelectorAll('[data-max-sub]')].map(el=>[el.dataset.maxSub,Number(el.value)]))}function refreshResultSubjects(){fillSelect('rSubject',subjects($('rClass').value));$('rMax').value=C.max[$('rExam').value]??20;$('sharedMax').value=C.max[$('rExam').value]??20}function updateAllMaxVisibility(){const same=$('sameMaxForAll').checked;$('sharedMaxField').classList.toggle('hidden',!same);$('allMaxFields').classList.toggle('hidden',resultMode==='one'||(resultMode==='all'&&same));if(resultMode==='all')loadGridResults()}$('sameMaxForAll').onchange=()=>{renderMaxFields();updateAllMaxVisibility()};$('sharedMax').onchange=()=>{if(resultMode==='all')loadGridResults()}; $('rClass').onchange=()=>{refreshResultSubjects();renderMaxFields();loadResultsForMode()};$('rExam').onchange=()=>{$('rMax').value=C.max[$('rExam').value]??20;renderMaxFields();loadResultsForMode()};$('rSection').onchange=()=>loadResultsForMode();$('rSubject').onchange=()=>loadResultsForMode();$('rMax').onchange=()=>{document.querySelectorAll('.class-mark').forEach(el=>el.max=$('rMax').value);const th=$('classResultsGrid').querySelector('thead th:last-child');if(th)th.textContent='Marks / '+$('rMax').value};refreshResultSubjects();let resultMode='one';function loadResultsForMode(){if(!resultMode)return;if(resultMode==='one'){if($('rClass').value&&$('rSection').value&&$('rExam').value&&$('rSubject').value)loadSingleResults()}else loadGridResults()}function setResultMode(m){resultMode=m;$('rSubjectField').classList.toggle('hidden',m!=='one');$('rMaxField').classList.toggle('hidden',m!=='one');$('allMaxSettings').classList.toggle('hidden',m!=='all');renderMaxFields();updateAllMaxVisibility();document.querySelectorAll('[data-result-mode]').forEach(b=>b.classList.toggle('active',b.dataset.resultMode===m));$('classResultsGrid').classList.toggle('hidden',m!=='one');$('allSubjectsGrid').classList.toggle('hidden',m!=='all');$('studentResultFilters').classList.toggle('hidden',m!=='student');$('studentResultsGrid').classList.toggle('hidden',m!=='student');$('loadClassResults').textContent='Refresh results (optional)';loadResultsForMode()}document.querySelectorAll('[data-result-mode]').forEach(b=>b.onclick=()=>setResultMode(b.dataset.resultMode));async function loadGridResults(){try{if(resultMode==='all'){const d=await api({action:'class_results_all',academic_session:C.session,class:$('rClass').value,section:$('rSection').value,exam:$('rExam').value});window.resultSubjects=d.subjects;$('allSubjectsGrid').innerHTML=d.students.length?'<div class="gridwrap"><table><thead><tr><th>Roll</th><th>Student</th><th>Student ID</th>'+d.subjects.map(x=>`<th>${esc(x)} / ${esc(maxMarksMap()[x]??C.max[$('rExam').value]??20)}</th>`).join('')+'</tr></thead><tbody>'+d.students.map(st=>`<tr><td>${esc(st.roll_no||'—')}</td><td>${esc(st.student_name)}</td><td>${esc(st.student_id)}</td>`+d.subjects.map(sub=>`<td><input class="all-mark" data-id="${esc(st.student_id)}" data-sub="${esc(sub)}" type="number" min="0" max="${esc(maxMarksMap()[sub]??C.max[$('rExam').value]??20)}" step="any" value="${d.saved[st.student_id]?.[sub]?.marks_obtained??''}" aria-label="${esc(st.student_name)} ${esc(sub)} marks"></td>`).join('')+'</tr>').join('')+'</tbody></table></div>':'<p class="notice">No enrolled students found.</p>';}
else if(resultMode==='student'){const previous=$('rsStudent').value;const d=await api({action:'class_results_all',academic_session:C.session,class:$('rClass').value,section:$('rSection').value,exam:$('rExam').value});fillSelect('rsStudent',d.students.map(x=>x.student_id),id=>{const st=d.students.find(x=>x.student_id===id);return `${st.roll_no||'—'} · ${st.student_name} (${id})`});if(d.students.some(x=>x.student_id===previous))$('rsStudent').value=previous;if(!d.students.length){$('studentResultsGrid').innerHTML='<p class="notice">No enrolled students found.</p>';return}const selected=$('rsStudent').value;const x=await api({action:'student_results',academic_session:C.session,class:$('rClass').value,section:$('rSection').value,exam:$('rExam').value,student_id:selected});$('studentResultsGrid').innerHTML='<p><strong>'+esc(x.student.student_name)+'</strong> · '+esc(x.student.student_id)+' · Roll '+esc(x.student.roll_no||'—')+'</p><div class="gridwrap"><table><thead><tr><th>Subject</th><th>Marks</th><th>Maximum</th></tr></thead><tbody>'+x.subjects.map(sub=>`<tr><td>${esc(sub)}</td><td><input class="student-mark" data-sub="${esc(sub)}" type="number" min="0" max="${esc(maxMarksMap()[sub]??C.max[$('rExam').value]??20)}" step="any" value="${x.saved[sub]?.marks_obtained??''}"></td><td>${esc(maxMarksMap()[sub]??x.saved[sub]?.max_marks??C.max[$('rExam').value]??20)}</td></tr>`).join('')+'</tbody></table></div>';$('rsStudent').onchange=loadGridResults;}}
catch(e){message(e.message,'error')}}async function loadSingleResults(){try{const d=await api({action:'class_results',academic_session:C.session,class:$('rClass').value,section:$('rSection').value,exam:$('rExam').value,subject:$('rSubject').value});const max=Number($('rMax').value||d.max_marks);$('rMax').value=max;$('classResultsGrid').innerHTML=d.rows.length?'<div class="gridwrap"><table><thead><tr><th>Roll</th><th>Student</th><th>Student ID</th><th>Marks / '+esc(max)+'</th></tr></thead><tbody>'+d.rows.map(r=>`<tr><td>${esc(r.roll_no)}</td><td>${esc(r.student_name)}</td><td>${esc(r.student_id)}</td><td><input class="class-mark" data-id="${esc(r.student_id)}" type="number" min="0" max="${esc(max)}" step="any" value="${r.marks_obtained===null?'':esc(r.marks_obtained)}" placeholder="—"></td></tr>`).join('')+'</tbody></table></div>': '<p class="notice">No enrolled students found for this selection.</p>'; }catch(e){message(e.message,'error')}}$('loadClassResults').onclick=async()=>{if(resultMode==='one')await loadSingleResults();else await loadGridResults()};$('saveClassResults').onclick=async()=>{try{if(resultMode==='one'){const marks=[...document.querySelectorAll('.class-mark')].map(x=>({student_id:x.dataset.id,marks:x.value}));if(!marks.length)throw Error('Load a class before saving marks.');const d=await api({action:'save_class_results',academic_session:C.session,class:$('rClass').value,section:$('rSection').value,exam:$('rExam').value,subject:$('rSubject').value,max_marks:$('rMax').value,rows:marks});message(`${d.saved} marks saved.`,'success');}
else if(resultMode==='all'){const subjects=window.resultSubjects||[];const ids=[...new Set([...document.querySelectorAll('.all-mark')].map(x=>x.dataset.id))];const marks=ids.map(id=>({student_id:id,marks:Object.fromEntries(subjects.map(sub=>[sub,document.querySelector(`.all-mark[data-id="${CSS.escape(id)}"][data-sub="${CSS.escape(sub)}"]`)?.value??'']))}));if(!marks.length)throw Error('Load a class before saving marks.');const maxMap=maxMarksMap();const d=await api({action:'save_result_grid',academic_session:C.session,class:$('rClass').value,section:$('rSection').value,exam:$('rExam').value,max_marks:maxMap,rows:marks});message(`${d.saved} marks saved.`,'success');}
else{const marks=[...document.querySelectorAll('.student-mark')].map(x=>({student_id:$('rsStudent').value,marks:{[x.dataset.sub]:x.value}}));if(!marks.length)throw Error('Load a student before saving marks.');const subjects=subjectsForCurrent();const d=await api({action:'save_result_grid',academic_session:C.session,class:$('rClass').value,section:$('rSection').value,exam:$('rExam').value,max_marks:maxMarksMap(),rows:[{student_id:$('rsStudent').value,marks:Object.fromEntries([...document.querySelectorAll('.student-mark')].map(x=>[x.dataset.sub,x.value]))}]});message(`${d.saved} marks saved.`,'success');}loadRecords();if(resultMode!=='one')loadGridResults();}catch(e){message(e.message,'error')}};function subjectsForCurrent(){return subjects($('rClass').value)}
$('refresh').onclick=loadRecords;$('studentStatusFilter').onchange=loadRecords;let studentSearchTimer;$('studentSearch').oninput=()=>{clearTimeout(studentSearchTimer);studentSearchTimer=setTimeout(loadRecords,220)};
$('resultWorkspace').classList.add('hidden');document.querySelector('.mode[data-mode="single"]').classList.add('hidden');$('single').classList.add('hidden');$('bulk').classList.remove('hidden');document.querySelectorAll('.mode').forEach(x=>x.classList.toggle('active',x.dataset.mode==='bulk'));$('seSession').value=C.session;fillSelect('seClass',C.classes,x=>'Class '+x);fillSelect('seSection',C.sections);renderForm();bulkRows=[bulkDefaults()];bulkTouched=[false];renderBulk();loadRecords();setResultMode('one');setTimeout(()=>loadResultsForMode(),0);
</script></body></html>
